parts.openscad_module:
$fn = 96;

// ── Main dimensions ──────────────────────────────────────
carriage_length = 40;   // X
carriage_width  = 70;   // Y
carriage_height = 30;   // Z

rod_spacing     = 40;   // LM8UU centre-to-centre (Y)
lm8uu_od        = 15;   // nominal LM8UU outer diameter

t8_screw_d      = 8;
t8_nut_od       = 22;
t8_nut_h        = 10;
nut_bolt_circle = 16;
nut_bolt_d      = 3.4;  // M3 clearance for FDM

// ── FDM bore allowances ───────────────────────────────────
bearing_fit  = 15.1;  // LM8UU press-fit bore (adjust after test print)
screw_clear  = 9.5;   // T8 screw clearance bore (screw_d + 1.5)
nut_pocket_d = 22.6;  // T8 nut pocket clearance (nut_od + 0.4 + 0.2)

// ── Body ─────────────────────────────────────────────────
module t8_nut_carriage() {
  difference() {
    cube([carriage_length, carriage_width, carriage_height], center = true);

    // LM8UU guide rod bores — horizontal, along X
    for (y = [-rod_spacing/2, rod_spacing/2])
      translate([0, y, 0])
        rotate([0, 90, 0])
          cylinder(h = carriage_length + 2, d = bearing_fit, center = true);

    // T8 lead screw clearance bore — vertical (Z), centred
    cylinder(h = carriage_height + 2, d = screw_clear, center = true);

    // T8 nut pocket — from top face, vertical (Z)
    translate([0, 0, carriage_height/2 - t8_nut_h/2])
      cylinder(h = t8_nut_h + 0.2, d = nut_pocket_d, center = true);

    // Nut capture bolt holes — M3 clearance = 3.4 mm, vertical (Z)
    for (a = [0, 90, 180, 270])
      rotate([0, 0, a])
        translate([nut_bolt_circle/2, 0, carriage_height/2 - t8_nut_h/2])
          cylinder(h = t8_nut_h + 4, d = nut_bolt_d, center = true);

    // Bottom material relief
    translate([0, 0, -carriage_height/2 + 5])
      cube([carriage_length - 8, carriage_width - 8, 8], center = true);
  }
}

t8_nut_carriage();
